ALTER TABLE viewer_manifest ADD CONSTRAINT uq_viewer_manifest_hash UNIQUE(scan_id,manifest_hash);
CREATE TABLE roi_head(scan_id uuid PRIMARY KEY,manifest_hash text NOT NULL,version bigint NOT NULL DEFAULT -1 CHECK(version>=-1),FOREIGN KEY(scan_id,manifest_hash) REFERENCES viewer_manifest(scan_id,manifest_hash));
CREATE TABLE roi_calibration(scan_id uuid NOT NULL REFERENCES roi_head(scan_id),version bigint NOT NULL CHECK(version>=0),mpp_x numeric NOT NULL CHECK(mpp_x>0 AND mpp_x<=100),mpp_y numeric NOT NULL CHECK(mpp_y>0 AND mpp_y<=100),basis text NOT NULL CHECK(basis='SYNTHETIC_TEST'),reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 200),actor_id uuid NOT NULL REFERENCES app_user(id),created_at timestamptz NOT NULL DEFAULT statement_timestamp(),PRIMARY KEY(scan_id,version));
CREATE TABLE roi_revision(scan_id uuid NOT NULL REFERENCES roi_head(scan_id),roi_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision BETWEEN 0 AND 99),collection_version bigint NOT NULL CHECK(collection_version>=0),author_id uuid NOT NULL REFERENCES app_user(id),actor_id uuid NOT NULL REFERENCES app_user(id),kind text NOT NULL CHECK(kind IN('POINT','RECTANGLE','POLYGON')),points jsonb NOT NULL CHECK(jsonb_typeof(points)='array' AND jsonb_array_length(points) BETWEEN 1 AND 32),deleted boolean NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 200),calibration_version bigint,measurement jsonb NOT NULL CHECK(jsonb_typeof(measurement)='object'),created_at timestamptz NOT NULL DEFAULT statement_timestamp(),PRIMARY KEY(scan_id,roi_id,revision),UNIQUE(scan_id,collection_version),FOREIGN KEY(scan_id,calibration_version) REFERENCES roi_calibration(scan_id,version));
CREATE TRIGGER trg_roi_revision_immutable BEFORE UPDATE OR DELETE ON roi_revision FOR EACH ROW EXECUTE FUNCTION protect_gross_append_only();
CREATE TRIGGER trg_roi_calibration_immutable BEFORE UPDATE OR DELETE ON roi_calibration FOR EACH ROW EXECUTE FUNCTION protect_gross_append_only();
CREATE FUNCTION guard_roi_head() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR NEW.scan_id<>OLD.scan_id OR NEW.manifest_hash<>OLD.manifest_hash OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Immutable ROI identity or stale version' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER trg_roi_head_version BEFORE UPDATE OR DELETE ON roi_head FOR EACH ROW EXECUTE FUNCTION guard_roi_head();
